/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for populating the TMS engine temp table (calculation table) for delivery note
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::SalesOrderCreation)]
final class METTMSEngineLinesTmpBuilder_Creation extends METTMSEngineLinesTmpBuilder
{
}

Method.Source:
/// <summary>
/// Validate if the line should be considered for TMS
/// </summary>
/// <param name = "_queryRun">Line selection query</param>
/// <returns>true, if the line should be considered otherwise, false</returns>
public boolean shouldIncludeLine(QueryRun _queryRun)
{
    boolean ret;

    ret = super(_queryRun);

    if(headerContract.isInternalCrossDockOrder())
    {
        METTMSSourceRecordLineMap lineRecord = this.getTablesQueryRun(_queryRun);

        //If the line quantity is '0' then is either picked or delivered fully 
        // and it will be part of the TMS order for picklist or shipment, so we do not need to include that in SO creation trigger
        if(this.lineShipQty(lineRecord) == 0)
        {
            ret = false;
        }
    }

    return ret;
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Sales order quantity</returns>
protected Qty lineShipQty(METTMSSourceRecordLineMap   _sourceLine)
{
    //We trigger TMS - SO Creation process multiple times for xDock sales orders with multiple TOs
    //So, we need to consider only the remaining quantity of SO Line as the picked/delivered quantity will be part of a different TMS order line
    return _sourceLine.OrderQty - _sourceLine.pickedInTotalSalesUnit() - _sourceLine.deliveredInTotal();
}
